import type {ListSessionsMessage, SessionListMessage} from './messages.js';

describe('list sessions message types', () => {
  it('allows ListSessionsMessage and SessionListMessage to be imported', () => {
    // This test verifies that the new message types exist and compile.
    // If these types don't exist, the import will fail at compile time.
    const incomingMessage: ListSessionsMessage = {
      type: 'list_sessions',
      limit: 10,
      before: {updatedAt: '2026-01-01T00:00:00.000Z', sessionId: 's1'},
    };

    const outgoingMessage: SessionListMessage = {
      type: 'session_list',
      sessions: [
        {
          sessionId: 's1',
          createdAt: '2026-01-01T00:00:00.000Z',
          updatedAt: '2026-01-01T00:05:00.000Z',
          entryCount: 2,
        },
      ],
    };

    expect(incomingMessage.type).toBe('list_sessions');
    expect(outgoingMessage.type).toBe('session_list');
  });
});

