import type {AddressInfo} from 'node:net';
import {WebSocket} from 'ws';
import type {Express} from 'express';
import {createServer} from './createServer.js';
import {HAL_WS_SUBPROTOCOL} from './ws/subprotocol.js';
import type {SessionStore} from '../types/sessionStore.js';

export interface TestFrame {
  type: string;
  sessionId?: string;
  sessions?: Array<{sessionId: string; createdAt: string; updatedAt: string; entryCount: number}>;
  code?: string;
  message?: string;
  resumed?: boolean;
  entryCount?: number;
  resumeFailure?: string;
  index?: number;
  entry?: unknown;
}

export const eventually = async (check: () => boolean): Promise<void> => {
  for (let attempt = 0; attempt < 50 && !check(); attempt++) {
    await new Promise(resolve => setTimeout(resolve, 10));
  }
};

export const createTestServerAndClients = () => {
  const servers: Array<ReturnType<typeof createServer>> = [];
  const clients: WebSocket[] = [];

  return {
    servers,
    clients,
    async cleanupAfterEach() {
      for (const client of clients.splice(0)) {
        client.terminate();
      }
      for (const hal of servers.splice(0)) {
        const {wss} = hal;
        await eventually(() => wss.clients.size === 0);
        await hal.stop();
      }
    },
  };
};

export const startEngine = async (
  servers: Array<ReturnType<typeof createServer>>,
  store: SessionStore,
  userId: string | number = 'u1',
  options?: {
    app?: Express;
    wsAuth?: (req: unknown) => Promise<{id: string | number}>;
  },
) => {
  const hal = createServer({
    app: options?.app ?? ((() => undefined) as unknown as Express),
    wsAuth: options?.wsAuth ?? (async () => ({id: userId})),
    sessionStore: store,
    orchestrator: (await import('./wsTestSupport.js')).answeringOrchestrator,
  });
  await hal.start(0);
  servers.push(hal);
  const {port} = hal.server.address() as AddressInfo;
  return `ws://127.0.0.1:${port}/hal/ws`;
};

export const askAfterConnect = async (
  clients: WebSocket[],
  url: string,
  outbound: unknown,
): Promise<{connected: TestFrame; frames: TestFrame[]}> => {
  const client = new WebSocket(url, [HAL_WS_SUBPROTOCOL, 't']);
  clients.push(client);
  const frames: TestFrame[] = [];
  let connected: TestFrame = {type: ''};
  await new Promise<void>(resolve => {
    client.on('message', raw => {
      const frame = JSON.parse(String(raw)) as TestFrame;
      if (frame.type === 'connected') {
        connected = frame;
        client.send(typeof outbound === 'string' ? outbound : JSON.stringify(outbound));
        client.send(JSON.stringify({type: 'ping', timestamp: 1}));
        return;
      }
      if (frame.type === 'pong') {
        resolve();
        return;
      }
      frames.push(frame);
    });
  });
  return {connected, frames};
};

